ALTER TABLE "bills" DROP CONSTRAINT "bills_series_valid";--> statement-breakpoint
ALTER TABLE "credit_card_expenses" DROP CONSTRAINT "credit_card_expenses_installment_valid";--> statement-breakpoint
ALTER TABLE "bills" ADD CONSTRAINT "bills_series_valid" CHECK (("bills"."series_id" is null and "bills"."series_number" is null and "bills"."series_total" is null) or ("bills"."series_id" is not null and "bills"."series_number" is not null and "bills"."series_total" is not null and "bills"."series_number" between 1 and "bills"."series_total" and "bills"."series_total" >= 2));--> statement-breakpoint
ALTER TABLE "credit_card_expenses" ADD CONSTRAINT "credit_card_expenses_installment_valid" CHECK (("credit_card_expenses"."installment_id" is null and "credit_card_expenses"."installment_number" is null and "credit_card_expenses"."installment_total" is null) or ("credit_card_expenses"."installment_id" is not null and "credit_card_expenses"."installment_number" is not null and "credit_card_expenses"."installment_total" is not null and "credit_card_expenses"."installment_number" between 1 and "credit_card_expenses"."installment_total" and "credit_card_expenses"."installment_total" >= 2));